/**
 * Contact - 联系方式区块
 * 站点级共享组件：微信号支持一键复制，邮箱支持点击发邮件。
 * 微信号是纯文本展示（没有 wx 协议），所以必须让用户能复制；
 * navigator.clipboard 在非 HTTPS 环境会失败，故降级为 execCommand。
 */
import { SITE_NAME } from './navigation';

export class Contact {
  constructor(options = {}) {
    this.wechat = options.wechat || 'zhenzi0322';
    this.email = options.email || '82131529@qq.com';
    this.title = options.title || '联系方式';
    this.description = options.description || '';
    this.note = options.note === false ? '' : `${SITE_NAME} · 作者 zhenzi0322`;
  }

  render() {
    const section = document.createElement('section');
    section.className = 'contact section';
    section.innerHTML = `
      <div class="container">
        ${this.title ? `<h2 class="heading-lg contact__title">${this.title}</h2>` : ''}
        ${this.description ? `<p class="text-muted contact__desc">${this.description}</p>` : ''}
        <div class="contact__grid">
          ${this.renderCard({
            icon: '💬',
            label: '微信',
            value: this.wechat,
            action: 'copy',
            hint: '点击复制微信号',
            tip: '日常沟通 · 最快回复',
          })}
          ${this.renderCard({
            icon: '✉️',
            label: '邮箱',
            value: this.email,
            action: 'mailto',
            hint: '点击发送邮件',
            tip: '发附件 · 详细描述',
          })}
        </div>
        ${this.note ? `<p class="contact__note text-muted">${this.note}</p>` : ''}
      </div>
    `;

    // 微信号一键复制
    const copyBtn = section.querySelector('[data-copy]');
    if (copyBtn) {
      copyBtn.addEventListener('click', () => this.handleCopy(copyBtn));
    }

    return section;
  }

  /** 联系方式卡片：图标 / 标签 / 值 / 用途提示 / 操作 */
  renderCard({ icon, label, value, action, hint, tip }) {
    const isCopy = action === 'copy';
    const tag = isCopy ? 'button' : 'a';
    const attrs = isCopy
      ? `type="button" class="contact__card" data-copy="${value}" title="${hint}"`
      : `href="mailto:${value}" class="contact__card" title="${hint}"`;

    return `
      <${tag} ${attrs}>
        <span class="contact__icon" aria-hidden="true">${icon}</span>
        <span class="contact__body">
          <span class="contact__label">${label}</span>
          <span class="contact__value">${value}</span>
          <span class="contact__tip">${tip}</span>
        </span>
        <span class="contact__action">
          <span class="contact__action-text">${isCopy ? '复制' : '发邮件'}</span>
        </span>
        <span class="contact__toast" role="status" aria-live="polite"></span>
      </${tag}>
    `;
  }

  async handleCopy(btn) {
    const text = btn.dataset.copy;
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
      } else {
        // 非 HTTPS / 旧浏览器降级
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.setAttribute('readonly', '');
        ta.style.position = 'absolute';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
      }
      this.setBtnState(btn, '已复制', true);
    } catch (err) {
      this.setBtnState(btn, '请手动复制', false);
    }
    setTimeout(() => this.setBtnState(btn, '复制', false), 2000);
  }

  setBtnState(btn, text, ok) {
    const action = btn.querySelector('.contact__action-text');
    if (action) action.textContent = text;
    btn.classList.toggle('is-copied', !!ok);
  }
}