/**
 * WeChatFollow - 微信公众号关注区块
 * 站点级共享组件：联系作者页使用。
 * 二维码图片放在 static/images/wechat/qrcode.jpg（copy-webpack-plugin 原样复制到 dist 根），
 * 引用时必须拼 SITE_BASE，子路径部署才不会错位。
 */
import { SITE_BASE, SITE_NAME } from './navigation';

const QR_IMAGE = `${SITE_BASE}images/wechat/qrcode.jpg`;

export class WeChatFollow {
  constructor(options = {}) {
    this.account = options.account || SITE_NAME;
    this.title = options.title || '关注微信公众号';
    this.description =
      options.description || `第一时间获取${SITE_NAME}旗下新应用与版本更新`;
    this.image = options.image || QR_IMAGE;
    this.points = options.points || ['新应用上线提醒', '版本更新说明', '使用技巧与答疑'];
  }

  render() {
    const section = document.createElement('section');
    section.className = 'wechat-follow section';
    section.innerHTML = `
      <div class="container">
        <div class="wechat-follow__card">
          <span class="wechat-follow__glow" aria-hidden="true"></span>

          <div class="wechat-follow__media">
            <div class="wechat-follow__qr">
              <img src="${this.image}" alt="${this.account} 微信公众号二维码" loading="lazy" />
            </div>
            <p class="wechat-follow__tip">微信扫一扫</p>
          </div>

          <div class="wechat-follow__text">
            <span class="wechat-follow__eyebrow">
              <span class="wechat-follow__dot" aria-hidden="true"></span>
              微信公众号
            </span>
            <h2 class="heading-md">${this.title}</h2>
            <p class="wechat-follow__desc">${this.description}</p>

            <ul class="wechat-follow__points">
              ${this.points
                .map((p) => `<li><span class="wechat-follow__check" aria-hidden="true">✓</span>${p}</li>`)
                .join('')}
            </ul>
          </div>
        </div>
      </div>
    `;
    return section;
  }
}