/**
 * 联系作者页面入口
 * 复用 Navbar / Footer / Contact / WeChatFollow 组件
 * 主体为联系方式卡片 + 常见问题说明
 */
import '../../styles/global.css';
import './style.css';
import {
  Navbar,
  Footer,
  Contact,
  WeChatFollow,
  BRAND,
  NAV_LINKS,
  FOOTER_LINKS,
  COPYRIGHT,
  SITE_NAME,
} from '../../components';

// ─── 常见问题 ───
const FAQ = [
  {
    icon: '🐛',
    title: '发现bug 反馈',
    description: '加微信直接说，或者邮件里附上复现步骤、截图和版本号，我这边处理更快。',
    action: '加微信说',
  },
  {
    icon: '💡',
    title: '功能建议',
    description: '你提的每一条我都会看。写得清楚、用得上的需求会优先排进版本计划。',
    action: '提一条建议',
  },
  {
    icon: '🤝',
    title: '合作与转载',
    description: '媒体转载、联合推广、技术交流都可以聊，先说明来意即可。',
    action: '说明来意',
  },
];

// ─── 渲染页面 ───
function renderPage() {
  const root = document.getElementById('app');
  if (!root) return;

  // Navbar
  const navbar = new Navbar({
    brand: BRAND,
    links: NAV_LINKS,
    activeKey: 'contact',
  });
  root.appendChild(navbar.render());

  // Hero
  const main = document.createElement('main');
  main.className = 'contact-hero';
  main.innerHTML = `
    <div class="container">
      <div class="contact-hero__inner">
        <h1 class="heading-xl">联系作者</h1>
        <p class="text-muted contact-hero__desc">
          ${SITE_NAME}下的每一款应用都是一个人做的。遇到问题、想提建议，或者只是想聊两句，
          下面的方式都能找到我。
        </p>
      </div>
    </div>
  `;
  root.appendChild(main);

  // 联系方式卡片（不重复大标题，页首已有「联系作者」）
  const contact = new Contact({
    description: '微信最快，邮箱适合发附件或详细描述。',
  });
  const contactEl = contact.render();
  contactEl.id = 'contact';
  root.appendChild(contactEl);

  // 什么时候找我
  const when = document.createElement('section');
  when.className = 'contact-when section section--alt';
  when.innerHTML = `
    <div class="container">
      <header class="contact-when__header">
        <h2 class="heading-lg">什么时候找我</h2>
        <p class="text-muted">这三种情况最常见，其余的随时都可以聊</p>
      </header>
      <div class="contact-when__grid">
        ${FAQ.map(
          (f, i) => `
            <div class="contact-when__card">
              <span class="contact-when__num">0${i + 1}</span>
              <div class="contact-when__icon" aria-hidden="true">${f.icon}</div>
              <h3 class="heading-md">${f.title}</h3>
              <p class="text-muted">${f.description}</p>
              <span class="contact-when__action">${f.action}</span>
            </div>
          `
        ).join('')}
      </div>
    </div>
  `;
  root.appendChild(when);

  // 公众号二维码
  const wechat = new WeChatFollow({
    title: '不想私聊也行',
    description: '关注公众号，第一时间获取书阁园旗下新应用与版本更新',
  });
  root.appendChild(wechat.render());

  // Footer
  const footer = new Footer({
    copyright: COPYRIGHT,
    links: FOOTER_LINKS,
  });
  root.appendChild(footer.render());
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', renderPage);
} else {
  renderPage();
}